CREATE TRIGGER `leafen_account_emails_user_insert` AFTER INSERT ON `users` WHEN trim(NEW.`email`) <> '' BEGIN
			INSERT INTO `leafen_account_emails` VALUES (lower(trim(NEW.`email`)), NEW.`id`, NEW.`verified`);
		END

CREATE TRIGGER `leafen_account_emails_user_update` AFTER UPDATE OF `email`, `verified` ON `users` BEGIN
			DELETE FROM `leafen_account_emails` WHERE `user_id` = OLD.`id`
				AND `email` = lower(trim(OLD.`email`)) AND lower(trim(OLD.`email`)) <> lower(trim(NEW.`email`));
			INSERT INTO `leafen_account_emails` (`email`, `user_id`, `verified`)
				SELECT lower(trim(NEW.`email`)), NEW.`id`, NEW.`verified` WHERE trim(NEW.`email`) <> ''
				ON CONFLICT (`email`) DO UPDATE SET `verified` = excluded.`verified`
				WHERE `user_id` = NEW.`id`;
			SELECT CASE WHEN trim(NEW.`email`) <> '' AND NOT EXISTS (
				SELECT 1 FROM `leafen_account_emails` WHERE `email` = lower(trim(NEW.`email`)) AND `user_id` = NEW.`id`
			) THEN RAISE(ABORT, 'LEAFEN_ACCOUNT_EXISTS') END;
		END

